"""Command-line chat client."""

import argparse
import socket


def main() -> None:
    parser = argparse.ArgumentParser(description="Connect to the chat server.")
    parser.add_argument("--host", default="127.0.0.1")
    parser.add_argument("--port", type=int, default=5050)
    args = parser.parse_args()
    with socket.create_connection((args.host, args.port)) as conn:
        for line in iter(input, "/quit"):
            conn.sendall((line + "\n").encode("utf-8"))


if __name__ == "__main__":
    main()


### framing.py
"""Length-prefixed frames: 4-byte big-endian length + UTF-8 body."""


def frame(message: str) -> bytes:
    body = message.encode("utf-8")
    return len(body).to_bytes(4, "big") + body


def unframe(buffer: bytes) -> tuple[list[str], bytes]:
    """Return the complete messages in buffer and the unused tail."""
    messages = []
    while len(buffer) >= 4:
        size = int.from_bytes(buffer[:4], "big")
        if len(buffer) < 4 + size:
            break
        messages.append(buffer[4:4 + size].decode("utf-8"))
        buffer = buffer[4 + size:]
    return messages, buffer


### protocol.py
"""Chat line protocol: slash commands."""


def parse_command(line: str) -> tuple[str, list[str]]:
    """Split a chat line into (command, args); plain text is ("say", [text])."""
    line = line.strip()
    if not line.startswith("/"):
        return "say", [line]
    name, _, rest = line[1:].partition(" ")
    if name == "nick":
        return "nick", [rest]
    if name == "msg":
        target, _, text = rest.partition(" ")
        return "msg", [target, text]
    if name == "quit":
        return "quit", []
    raise ValueError(f"unknown command /{name}")


### room.py
"""The chat room: connected clients by nickname."""

import threading


class Room:
    def __init__(self) -> None:
        self._lock = threading.Lock()
        self._clients: dict[str, object] = {}

    def join(self, nick: str, conn: object) -> bool:
        """Add a client; False if the nickname is taken (case-insensitive)."""
        with self._lock:
            if nick.lower() in self._clients:
                return False
            self._clients[nick.lower()] = conn
            return True

    def leave(self, nick: str) -> None:
        with self._lock:
            self._clients.pop(nick.lower(), None)

    def broadcast(self, text: str) -> int:
        """Send text to every open connection, drop closed ones; return how many got it."""
        sent = 0
        with self._lock:
            for nick, conn in self._clients.items():
                if conn.closed:
                    del self._clients[nick]
                    continue
                conn.send(text)
                sent += 1
        return sent


### server.py
"""Line echo server for the chat project."""

import socket


class EchoServer:
    def __init__(self, host: str = "127.0.0.1", port: int = 0) -> None:
        self.sock = socket.create_server((host, port))
        self.port = self.sock.getsockname()[1]

    def handle(self, conn: socket.socket) -> None:
        """Reply "echo: <line>" to every line the client sends."""
        with conn, conn.makefile("r", encoding="utf-8") as lines:
            for line in lines:
                conn.sendall(f"echo: {line.strip()}\n".encode("utf-8"))

    def serve_forever(self) -> None:
        while True:
            conn, _ = self.sock.accept()
            self.handle(conn)

